class Counter {
  constructor(limit) { this.limit = limit; }
  [Symbol.iterator]() {
    let n = 0;
    const limit = this.limit;
    return {
      next() {
        return n < limit ? { value: n++, done: false } : { done: true };
      }
    };
  }
}
console.log([...new Counter(3)]);
